# Model Loading Function
@st.cache_resource
def load_keras_model():
    """
    Builds and reconstructs the custom Sequential CNN model architecture as specified in the project documentation.
    """
    model = tf.keras.models.Sequential([
        tf.keras.layers.Input(shape=(224, 224, 3)),
        tf.keras.layers.Conv2D(32, (3, 3), activation='relu'),
        tf.keras.layers.MaxPooling2D((2, 2)),
        tf.keras.layers.Conv2D(64, (3, 3), activation='relu'),
        tf.keras.layers.MaxPooling2D((2, 2)),
        tf.keras.layers.Conv2D(128, (3, 3), activation='relu'),
        tf.keras.layers.MaxPooling2D((2, 2)),
        tf.keras.layers.Flatten(),
        tf.keras.layers.Dense(128, activation='relu'),
        tf.keras.layers.Dropout(0.5),
        tf.keras.layers.Dense(1, activation='sigmoid')
    ])
    model.compile(optimizer='adam', loss='binary_cross_entropy', metrics=['accuracy'])
    return model

# Image Processing Function
def preprocess_and_predict(image, model):
    img = image.convert('RGB')
    img = img.resize((224, 224))
    img_array = np.array(img) / 255.0
    img_array = np.expand_dims(img_array, axis=0)
    
    prediction = model.predict(img_array)
    confidence = float(prediction[0][0])
    
    # Class mapping based on binary threshold
    if confidence >= 0.5:
        label = "Parkinson Detected (YES)"
        score = confidence
        is_affected = True
    else:
        label = "Not Affected (NO)"
        score = 1.0 - confidence
        is_affected = False
        
    return label, score, is_affected

